package binarycodec

import "testing"

// Blobs taken from the rippled 3.4.1 conformance corpus: a RippleState entry,
// the metadata of an OfferCreate touching offers, trust lines and accounts, an
// AccountRoot entry and a signed XRP Payment.
var codecBenchBlobs = []struct{ name, hex string }{
	{"RippleState", ""},
	{"OfferCreateMeta", ""},
	{"AccountRoot", "1100612200800000240000000525000000042D00000000552AA90AEC0FBA5EDE8473A6B208D9E673D3DB36CDD40D785F08FA83FFE40F329D624000000253FCA1B68114AE123A8556F3CF91154711376AFB0F894F832B3D"},
	{"Payment", ""},
}

func BenchmarkDecode(b *testing.B) {
	for _, bc := range codecBenchBlobs {
		b.Run(bc.name, func(b *testing.B) {
			b.ReportAllocs()
			for b.Loop() {
				if _, err := Decode(bc.hex); err != nil {
					b.Fatal(err)
				}
			}
		})
	}
}

func BenchmarkEncode(b *testing.B) {
	for _, bc := range codecBenchBlobs {
		b.Run(bc.name, func(b *testing.B) {
			m, err := Decode(bc.hex)
			if err != nil {
				b.Fatal(err)
			}
			b.ReportAllocs()
			for b.Loop() {
				if _, err := Encode(m); err != nil {
					b.Fatal(err)
				}
			}
		})
	}
}
